def resolve(path, cwd, links):
    if not cwd or cwd[0] != '/' or (len(cwd) > 1 and cwd[-1] == '/'):
        return None

    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        if not remaining:
            if current == '/':
                return '/'
            else:
                return current

        component, _, remaining = remaining.partition('/')

        if component == '' or component == '.':
            continue

        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0] if '/' in current[1:] else '/'
            continue

        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            if target.startswith('/'):
                current = '/'
                remaining = target[1:] + ('/' + remaining if remaining else '')
            else:
                if current == '/':
                    current = '/'
                    remaining = target + ('/' + remaining if remaining else '')
                else:
                    parent = current.rsplit('/', 1)[0] if '/' in current[1:] else '/'
                    current = parent
                    remaining = target + ('/' + remaining if remaining else '')
        else:
            current = next_path

    return None

